const DRAG_PX_PER_ROW = 62;
/** Pointer travel before a press is treated as a drag rather than a click. */
const DRAG_THRESHOLD_PX = 6;
const ROW_LEFT = 34;
/** Left column holding the era's anchor year. */
const GUTTER = 86;
/** Space between the gutter and the name, where the tick sits. */
const TICK_GAP = 38;
const TICK_WIDTH = 16;
const TICK_LEFT = ROW_LEFT + GUTTER + (TICK_GAP - TICK_WIDTH) / 2;

const SERIF = "var(--font-instrument-serif), Georgia, serif";
const MONO = "var(--font-plex-mono), ui-monospace, Menlo, monospace";
const EDGE_FADE =
  "linear-gradient(to bottom, transparent 0%, #000 24%, #000 76%, transparent 100%)";

const THEMES = {
  paper: {
    bg: "#fbf9f5",
    ink: "#101010",
    dim: "rgba(16,16,16,0.5)",
    rule: "rgba(16,16,16,0.09)",
    accent: "#8c3a2e"
  },
  dusk: {
    bg: "transparent",

    bg: "transparent",
    ink: "#f5efe2",
    dim: "rgba(245,239,226,0.52)",
    rule: "rgba(245,239,226,0.13)",
    accent: "#d4b16a"
