    (next: number) => {
      const clamped = Math.min(periods.length - 1, Math.max(0, next));
      const period = periods[clamped];
      if (!period || period.id === selectedId) return;
      if (value === undefined) setInternal(period.id);
      onChange?.(period, clamped);
