                  display: "flex",
                  alignItems: "center",
                  gap: TICK_GAP,
                  cursor: "pointer",
                  opacity: distance === 0 ? 1 : distance === 1 ? 0.32 : 0.13,
                  transform: `scale(${selected ? 1 : 0.86})`,
                  transformOrigin: "left center"
                }}
              >
                {showConcurrency && concurrent.has(period.id) && (
                  <div
                    aria-hidden
                    className="period-tie"
                    style={{
                      position: "absolute",
                      left: -16,
                      width: 1,
                      top: tiesUp.has(period.id) ? -ROW / 2 : 30,
                      bottom: tiesDown.has(period.id) ? -ROW / 2 : 30,
                      background: t.accent,
                      opacity: distance <= 1 ? 0.7 : 0.22
                    }}
                  />
                )}
                <div
                  style={{
                    width: GUTTER,
                    flex: "none",
                    textAlign: "right",
                    font: `400 20px/1 ${MONO}`,
                    letterSpacing: "0.02em",
                    color: t.dim,
                    whiteSpace: "nowrap"
                  }}
                >
                  {period.label}
                </div>
                <div
                  style={{
                    font: `400 24px/1.15 ${SERIF}`,
                    letterSpacing: "-0.015em",
                    color: t.ink
                  }}
                >
                  {period.name}
                </div>
              </div>
            );
          })}
        </div>

        <div
          aria-hidden
          style={{
            position: "absolute",
            left: TICK_LEFT,
            top: "50%",
            width: TICK_WIDTH,
            height: 1,
            background: t.accent,
            zIndex: 3
          }}
        />
      </div>

      {showNote && current?.note && (
        <div style={{ borderTop: `1px solid ${t.rule}`, margin: `0 ${ROW_LEFT}px`, padding: "14px 0 4px" }}>
          <div style={{ font: `400 11px/1.5 ${MONO}`, letterSpacing: "0.06em", color: t.dim }}>
            {current.note}
          </div>
        </div>
      )}
    </div>
  );
}

